import products from './products.json' with {type:'json'};

const SEARCH_TOOL = {
  name: 'inventory_search',
  description: 'Search inventory products by name (case-insensitive substring match).',
  inputSchema: {
    type: 'object',
    properties: {
      query: {
        type: 'string',
        minLength: 1,
        description: 'Substring to search for in product names.'
      },
      limit: {
        type: 'integer',
        minimum: 1,
        maximum: 10,
        description: 'Maximum number of results to return (1-10).'
      }
    },
    required: ['query'],
    additionalProperties: false
  }
};

export async function listTools() {
  return [SEARCH_TOOL];
}

function fail(message) {
  const err = new Error(message);
  err.code = -32602;
  throw err;
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    fail(`Unknown tool: ${name}`);
  }

  const { query, limit } = args || {};

  if (typeof query !== 'string' || query.length === 0) {
    fail('Invalid arguments: query must be a non-empty string');
  }

  if (limit !== undefined && (!Number.isInteger(limit) || limit < 1 || limit > 10)) {
    fail('Invalid arguments: limit must be an integer between 1 and 10');
  }

  const needle = query.toLowerCase();
  const matches = products.filter(p => p.name.toLowerCase().includes(needle));
  const limited = limit === undefined ? matches : matches.slice(0, limit);

  const text = limited.length === 0
    ? 'No products matched.'
    : limited.map(p => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}

