{"command":"node -e "
import('./server.mjs').then(async ({callTool, listTools}) => {
  const tools = await listTools();
  console.log('Tools:', JSON.stringify(tools, null, 2));

  // Happy path with limit
  const r1 = await callTool('inventory_search', {query:'pen', limit:1});
  console.log('Limit 1:', r1.content[0].text);

  // Case-insensitive
  const r2 = await callTool('inventory_search', {query:'NOTE'});
  console.log('NOTE search:', r2.content[0].text);

  // No match
  const r3 = await callTool('inventory_search', {query:'xyz'});
  console.log('No match:', r3.content[0].text);

  // Errors
  const cases = [
    ['missing query', () => callTool('inventory_search', {})],
    ['empty query', () => callTool('inventory_search', {query:''})],
    ['non-string query', () => callTool('inventory_search', {query:5})],
    ['limit=0', () => callTool('inventory_search', {query:'pen', limit:0})],
    ['limit=11', () => callTool('inventory_search', {query:'pen', limit:11})],
    ['limit non-int', () => callTool('inventory_search', {query:'pen', limit:1.5})],
    ['unknown tool', () => callTool('foo', {query:'x'})],
  ];
  for (const [label, fn] of cases) {
    try { await fn(); console.log(label, '=> NO ERROR (bug!)'); }
    catch (e) { console.log(label, '=>', e.message); }
  }
});
" 2>&1"}

